param([string]$Source=(Join-Path $PSScriptRoot '..\docs\deliverables\GameNarrator学年设计论文.docx'),[string]$Output=(Join-Path $PSScriptRoot '..\docs\deliverables\GameNarrator学年设计论文-20至30页版.docx'))
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem
Copy-Item -LiteralPath $Source -Destination $Output -Force
function X([string]$s){[Security.SecurityElement]::Escape($s)}
function Para([string]$t,[bool]$heading=$false){$style=if($heading){'<w:pStyle w:val="2"/><w:keepNext/><w:spacing w:before="240" w:after="120"/><w:jc w:val="left"/>'}else{'<w:spacing w:line="440" w:lineRule="exact"/><w:ind w:firstLine="480"/><w:jc w:val="both"/>'};$font=if($heading){'<w:b/><w:bCs/><w:sz w:val="28"/><w:szCs w:val="28"/>'}else{'<w:sz w:val="24"/><w:szCs w:val="24"/>'};'<w:p><w:pPr>'+$style+'</w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:eastAsia="宋体"/>'+$font+'</w:rPr><w:t xml:space="preserve">'+(X $t)+'</w:t></w:r></w:p>'}
function Page(){'<w:p><w:r><w:br w:type="page"/></w:r></w:p>'}
$sections=@(
@('4.6 Web端任务工作台实现','Web端承担完整创作流程的主要交互。首页集中展示项目列表、当前任务、运行阶段和最终成片入口，使用户可以从一次导入开始完成处理。任务创建表单只保留视频来源、目标时长、解说风格和输出质量等高频参数，模型、编码器和素材策略放在高级设置中，以减少初次使用时的认知负担。','任务提交后，前端定时读取后端状态并显示阶段名称、子进度、已完成数量和当前操作。刷新页面不会丢失任务，因为真实状态由数据库保存。对于失败任务，界面同时显示简短原因、可执行建议和追踪号，用户能够据此启动本地依赖、安装模型或重新授权素材。','前端模块通过统一API客户端访问REST接口，集中处理超时、非JSON响应和网络断开。生产构建输出由Spring Boot托管，使Windows桌面入口和浏览器访问同一套页面，降低重复维护成本。'),
@('4.7 分镜、脚本与时间线实现','自动分析完成后，系统把候选片段转换为可编辑分镜。每个分镜包含源视频起止时间、代表帧、视觉描述、转写片段、高光分值和采用理由。用户可以锁定重要镜头、排除无关镜头、调整排序或修改持续时间，人工决定会写入项目修订记录。','脚本编辑器按分镜保存解说文本、字幕文本和生成依据。重新生成时，新结果形成独立版本，不直接覆盖用户已经确认的文本。版本切换会重新判断配音与时间线是否仍然有效，防止旧音频与新文案长度不一致。','时间线把画面、原声、配音、字幕、音乐、贴图和转场统一到毫秒坐标。渲染前生成只读快照，使用户继续编辑项目时不会改变正在执行的导出任务。'),
@('4.8 Windows EXE桌面入口实现','Windows版本使用Launcher作为桌面入口。启动器首先读取安装目录和数据目录，检查Java运行环境、FFmpeg、本地模型服务与端口占用，然后启动Spring Boot并等待健康检查通过。服务就绪后再打开浏览器页面，避免用户看到尚未启动完成的空白页。','安装程序允许把程序、模型和工作数据放在非系统盘。启动器不假定固定盘符，而是根据安装配置构造绝对路径；涉及用户素材的路径还会在后端转换为存储根目录下的受控相对路径。','退出时，Launcher先请求后端安全停止，再等待任务保存检查点。如果超时才终止已登记的进程树。该策略兼顾桌面应用易用性与Web服务长任务特征，也能减少重复启动造成的端口占用。'),
@('4.9 Android移动端实现','Android端定位为移动工作台，主要提供任务创建、进度查看、结果预览、模型能力检查和基础设置。它通过HTTP接口连接同一后端，因此项目状态、阶段结果与Web端保持一致。','移动端根据屏幕宽度采用纵向卡片布局，对任务状态使用颜色、图标和文字共同表达。网络中断时保留最后一次成功数据并提供重试入口；后端不可访问时显示服务器地址和诊断建议。','涉及文件选择和网络访问的能力通过Android权限与系统文档选择器实现。应用不直接扫描用户全部存储空间，上传前显示文件名、大小和目标项目，符合最小权限原则。'),
@('4.10 本地模型服务与推理适配','模型设置页从Ollama运行时查询实际已安装模型，只有能够匹配任务能力的模型才进入可选列表。项目历史记录中的云端名称仅用于说明当时使用的引擎，不能直接作为本地Ollama请求模型，从而避免名称混用产生HTTP 404。','视觉理解默认使用Qwen2.5-VL处理代表帧、OCR文字和事件线索。为控制显存与等待时间，系统先对低成本证据评分，再决定是否扩展前后帧；请求包含超时、并发上限和结构化输出要求。','导演评审会包含事实、剧情、节奏和受众四类角色。最终结论作为建议保存，不自动覆盖分镜与时间线，确保生成模型不会绕过用户确认直接修改作品。'),
@('4.11 素材检索、授权与降级处理','素材模块区分用户本地文件、公开许可素材和需要账户授权的平台内容。素材记录包含来源、作者、许可类型、原始链接、下载时间和用途范围；未确认授权的素材不能自动加入时间线。','当Wikimedia等外部来源暂时无法连接时，系统跳过该来源并继续检查本地素材库和其他可用来源。所有来源均不可用时返回明确的空结果，而不是无限等待；BGM、视频和表情素材分别记录失败原因。','下载任务使用临时文件，校验类型与大小后再原子移动到素材目录。远程地址经过协议、主机和重定向检查，Cookie与访问令牌只在请求期间使用，不写入普通诊断日志。'),
@('4.12 数据库表结构与迁移机制','核心实体包括视频任务、处理阶段、阶段产物、素材、脚本版本、分镜放置、时间线版本和导出记录。任务保存总体状态与用户参数，阶段表保存九阶段执行信息，产物表保存文件类型、相对路径、大小和指纹。','Flyway在应用启动时按版本号执行迁移。诊断代码查询迁移历史前判断当前数据库类型和历史表是否存在，避免在未启用Flyway或测试数据库中直接执行不兼容SQL。','大文件不存入数据库。任务目录以UUID命名，数据库只保存相对存储键。读取、导出和删除前都通过规范化路径检查目标仍位于配置根目录内。'),
@('4.13 安全性与隐私保护设计','系统把本地优先作为默认数据策略。原视频、抽帧、转写、模型文件、配音和导出结果均可保存到用户指定的非系统盘目录，本地模式不要求登录云账户，也不自动上传作品内容。','文件接口使用白名单类型、大小限制、随机文件名和路径归属检查。远程下载防止服务端请求伪造，压缩包解压限制文件数量、总大小和目标路径。日志过滤令牌、Cookie和本机敏感目录。','长任务取消采用终态优先原则：先在数据库记录取消状态，再向外部进程发送终止信号。恢复器不会把用户主动取消的任务重新标记为失败，也不会自动启动。'),
@('4.14 测试方案与结果分析','测试采用单元测试、集成测试、前端模块测试、构建检查和人工验收相结合的方法。后端重点覆盖状态转换、检查点恢复、路径归属、模型返回解析、素材授权、时间线校验和渲染命令生成。','项目记录的完整Maven测试包含337项，结果为0失败、0错误、4项环境跳过。跳过项目主要依赖特定外部程序或设备，不能等同于功能已经在所有硬件上通过。','日常开发使用快速检查脚本优先发现配置错误、JavaScript语法、公共资源错误导入和少量高价值回归。涉及数据库、任务恢复或媒体流程的修改仍需运行对应专项测试。'),
@('4.15 部署流程与运行环境','开发环境需要Java 21、Maven Wrapper、Node.js、Android SDK以及可选的桌面启动器工具链。媒体与人工智能依赖包括FFmpeg、whisper.cpp、Ollama视觉模型和Piper语音模型。','Web开发模式由Vite提供热更新，Spring Boot提供后端接口；生产模式先构建前端静态资源，再打包后端与启动器。Android端通过Gradle构建APK，服务器地址在设置页配置。','部署验证包括数据库迁移、磁盘空间、模型列表、FFmpeg编码器、Whisper可执行文件、Piper音色和健康接口。诊断结果使用红、黄、绿区分失败、提醒与通过。'),
@('4.16 系统局限与改进方向','当前系统已经实现三端入口与完整处理闭环，但真实视频效果仍受游戏类型、录音质量、显卡显存、模型量化和提示词影响。自动化测试可以验证流程和数据一致性，不能代替对高光准确度、解说自然度和成片节奏的主观评价。','部分高级功能对普通用户使用频率较低。后续应根据真实任务数据统计功能使用率，把首页进一步收敛为导入、生成、复核和导出四步；模型管理、素材来源、导演评审和高级时间线保留在专业模式中。','性能方面可建立不同分辨率和时长的基准集，记录分析实时率、显存峰值、字幕误差和渲染耗时。质量方面可邀请多名用户进行盲评，统计高光命中率、文案修改比例和最终采用率。')
)
$zip=[IO.Compression.ZipFile]::Open([IO.Path]::GetFullPath($Output),[IO.Compression.ZipArchiveMode]::Update)
try{$entry=$zip.GetEntry('word/document.xml');$reader=New-Object IO.StreamReader($entry.Open(),[Text.Encoding]::UTF8);$xml=$reader.ReadToEnd();$reader.Close();$insert=$xml.LastIndexOf('<w:sectPr');if($insert-lt 0){$insert=$xml.LastIndexOf('</w:body>')};$content='';foreach($s in $sections){$content+=Page;$content+=Para $s[0] $true;for($i=1;$i-lt $s.Count;$i++){$content+=Para $s[$i]}};$xml=$xml.Insert($insert,$content);$entry.Delete();$new=$zip.CreateEntry('word/document.xml');$writer=New-Object IO.StreamWriter($new.Open(),[Text.UTF8Encoding]::new($false));$writer.Write($xml);$writer.Close()}finally{$zip.Dispose()}
"OUTPUT=$Output`nADDED_PAGES=$($sections.Count)"
